import csv
import math
import subprocess
import sys
import tempfile
from pathlib import Path

bin_path=sys.argv[1]
cases=[{"name":"atlas-tail-tail-frequency","x":[1,2,3,4],"y":[1,1,1,1],"p":2.5,"expected":0.5},{"name":"atlas-tail-mean-excess","x":[1,2,3,4],"y":[1,1,1,1],"p":2.5,"expected":1},{"name":"atlas-tail-conditional-tail-mean","x":[1,2,3,4],"y":[1,1,1,1],"p":2.5,"expected":3.5},{"name":"atlas-tail-exceedance-second-moment","x":[1,2,3,4],"y":[1,1,1,1],"p":2.5,"expected":0.625},{"name":"atlas-tail-weighted-expected-shortfall","x":[1,2,3,4],"y":[1,1,1,1],"p":0.5,"expected":3.5},{"name":"atlas-robust-huber-objective","x":[0,2],"y":[0,0],"p":1,"expected":0.75},{"name":"atlas-robust-pseudo-huber","x":[0,2],"y":[0,0],"p":1,"expected":0.6180339887498949},{"name":"atlas-robust-cauchy-objective","x":[0,2],"y":[0,0],"p":1,"expected":0.40235947810852507},{"name":"atlas-robust-scaled-log-cosh","x":[0,1],"y":[0,0],"p":1,"expected":0.21689041524151356},{"name":"atlas-robust-tukey-biweight","x":[0,2],"y":[0,0],"p":1,"expected":0.08333333333333333},{"name":"atlas-macro-after-tax-real-growth","x":[0.1],"y":[0.02],"p":0.1,"expected":0.06862745098039214},{"name":"atlas-macro-real-rate-gap","x":[0.1],"y":[0.02],"p":0.02,"expected":0.05843137254901977},{"name":"atlas-macro-taylor-zero-target","x":[0.02],"y":[0.01],"p":0.02,"expected":0.055},{"name":"atlas-macro-gdp-deflator-level","x":[120],"y":[100],"p":100,"expected":120},{"name":"atlas-macro-cpi-deflated-wage","x":[110],"y":[110],"p":100,"expected":100},{"name":"atlas-forecast-wape-guarded","x":[1,3],"y":[2,2],"p":1,"expected":0.5},{"name":"atlas-forecast-symmetric-mape","x":[1,3],"y":[2,2],"p":1,"expected":0.6666666666666666},{"name":"atlas-forecast-mean-log-cosh-error","x":[0,1],"y":[0,0],"p":1,"expected":0.21689041524151356},{"name":"atlas-forecast-epsilon-tube-mae","x":[1,3],"y":[2,2],"p":0.5,"expected":0.5},{"name":"atlas-forecast-threshold-class-hit","x":[1,3],"y":[2,2],"p":2.5,"expected":0.5},{"name":"atlas-dependence-downside-cohit","x":[-2,-1,1,2],"y":[-3,1,-1,3],"p":0,"expected":0.25},{"name":"atlas-dependence-conditional-downside","x":[-2,-1,1,2],"y":[-3,1,-1,3],"p":0,"expected":0.5},{"name":"atlas-dependence-upside-cohit","x":[-2,-1,1,2],"y":[-3,1,-1,3],"p":0,"expected":0.25},{"name":"atlas-dependence-conditional-downside-beta","x":[-2,-1,1,2],"y":[-3,1,-1,3],"p":0,"expected":4},{"name":"atlas-dependence-downside-relative-spread","x":[-2,-1,1,2],"y":[-3,1,-1,3],"p":0,"expected":0.5},{"name":"atlas-execution-participation-headroom","x":[1,3,1,2],"y":[10,10,5,10],"p":0.2,"expected":0},{"name":"atlas-execution-overcap-window-share","x":[1,3,1,2],"y":[10,10,5,10],"p":0.2,"expected":0.25},{"name":"atlas-execution-exceeding-market-volume","x":[1,3,1,2],"y":[10,10,5,10],"p":0.2,"expected":1},{"name":"atlas-execution-peak-participation-utilization","x":[1,3,1,2],"y":[10,10,5,10],"p":0.2,"expected":1.5},{"name":"atlas-execution-participation-target-deviation","x":[1,3,1,2],"y":[10,10,5,10],"p":0.2,"expected":0.005},{"name":"atlas-signals-signal-hit-rate","x":[1,2,3,4],"y":[-1,1,2,3],"p":2.5,"expected":1},{"name":"atlas-signals-signal-conditional-payoff","x":[1,2,3,4],"y":[-1,1,2,3],"p":2.5,"expected":2.5},{"name":"atlas-signals-signal-signed-return","x":[1,2,3,4],"y":[-1,1,2,3],"p":2.5,"expected":1.25},{"name":"atlas-signals-signal-top-bottom-spread","x":[1,2,3,4],"y":[-1,1,2,3],"p":0.25,"expected":4},{"name":"atlas-signals-signal-ic-excess","x":[1,2,3,4],"y":[1,2,3,4],"p":0.1,"expected":0.9},{"name":"atlas-cashflows-cashflow-present-value","x":[1,2],"y":[10,20],"p":0,"expected":30},{"name":"atlas-cashflows-cashflow-discounted-duration","x":[1,2],"y":[10,20],"p":0,"expected":1.6666666666666667},{"name":"atlas-cashflows-cashflow-time-dispersion","x":[1,2],"y":[10,20],"p":0,"expected":0.4714045207910317},{"name":"atlas-cashflows-cashflow-coverage-ratio","x":[0,1,2],"y":[-10,5,10],"p":0,"expected":1.5},{"name":"atlas-cashflows-cashflow-discounted-payback","x":[0,1,2],"y":[-10,5,10],"p":0,"expected":1.5},{"name":"atlas-wealth-relative-log-wealth","x":[0.1,-0.1],"y":[0,0],"p":0,"expected":-0.01005033585350145},{"name":"atlas-wealth-relative-wealth-max-drawdown","x":[0.1,-0.1],"y":[0,0],"p":0,"expected":0.1},{"name":"atlas-wealth-excess-return-hurdle-hit","x":[0.1,-0.1],"y":[0,0],"p":0.05,"expected":0.5},{"name":"atlas-wealth-relative-volatility-drag","x":[0.1,-0.1],"y":[0,0],"p":0,"expected":0.005012562893380035},{"name":"atlas-wealth-relative-terminal-wealth","x":[0.1,-0.1],"y":[0,0],"p":0,"expected":0.99},{"name":"atlas-credit-portfolio-expected-credit-loss","x":[0.1,0.2],"y":[0.5,0.25],"p":100,"expected":10},{"name":"atlas-credit-independent-credit-loss-variance","x":[0.1,0.2],"y":[0.5,0.25],"p":100,"expected":325},{"name":"atlas-credit-high-lgd-expected-defaults","x":[0.1,0.2],"y":[0.5,0.25],"p":0.3,"expected":0.1},{"name":"atlas-credit-expected-credit-recovery","x":[0.1,0.2],"y":[0.5,0.25],"p":100,"expected":20},{"name":"atlas-credit-independent-credit-loss-sd","x":[0.1,0.2],"y":[0.5,0.25],"p":100,"expected":18.027756377319946}]
with tempfile.TemporaryDirectory() as temporary:
    for case in cases:
        path=Path(temporary)/(case["name"]+".csv")
        with path.open("w",newline="",encoding="utf-8") as handle:
            writer=csv.writer(handle)
            writer.writerow(["X","Y"])
            for x,y in zip(case["x"],case["y"]):
                writer.writerow([x,y])
        args=[bin_path,case["name"],str(path),"X","Y",str(case["p"])]
        completed=subprocess.run(args,capture_output=True,text=True,timeout=20)
        assert completed.returncode==0,(args,completed.stderr)
        parts=completed.stdout.strip().split(",")
        assert len(parts)==2 and parts[0]=="Value", (args,completed.stdout)
        observed=float(parts[1])
        assert math.isfinite(observed) and math.isclose(
          observed,case["expected"],rel_tol=1e-7,abs_tol=1e-7
        ),(args,case["expected"],observed)
        for broken in ([bin_path,case["name"],str(path),"X","Missing",str(case["p"])],
                       [bin_path,case["name"],str(path),"X","Y","invalid-scalar"]):
            result=subprocess.run(broken,capture_output=True,text=True,timeout=20)
            assert result.returncode==1,(broken,result.stdout,result.stderr)
            assert "Quant research input error:" in result.stderr,broken
    print(f"PASS: {len(cases)} quantitative CSV workflows, {len(cases)*2} malformed-input checks")
